<?php $title='Members & Permissions'; ?>
<div class="page-head"><div><span class="eyebrow">ACCESS CONTROL</span><h1>Members &amp; Permissions</h1><p>Chỉ Admin tạo tài khoản, gán role và cấp quyền xem nhật ký.</p></div></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Thành viên dự án</h2><p><?= count($members) ?> tài khoản</p></div></div><?php foreach($members as $member): ?><form method="post" action="<?= e(url('members/permissions')) ?>" class="member-card"><?= csrf_field() ?><input type="hidden" name="membership_id" value="<?= (int)$member['id'] ?>"><div class="member-head"><span class="avatar"><?= e(strtoupper(substr($member['name'],0,2))) ?></span><div><strong><?= e($member['name']) ?></strong><small><?= e($member['email']) ?></small></div><span class="pill <?= $member['role']==='admin'?'green':'gray' ?>"><?= e($member['role']) ?></span></div><?php if($member['role']!=='admin'): ?><div class="permission-grid"><label>Vai trò<select name="role"><option value="viewer" <?= $member['role']==='viewer'?'selected':'' ?>>Viewer</option><option value="editor" <?= $member['role']==='editor'?'selected':'' ?>>Editor</option></select></label><label class="check-label"><input type="checkbox" name="can_view_audit" <?= $member['can_view_audit']?'checked':'' ?>> Xem audit log</label></div><p class="muted">Editor chỉ sửa được feature được chọn.</p><div class="flag-permissions"><?php foreach($flags as $flag): ?><label><input type="checkbox" name="flag_ids[]" value="<?= (int)$flag['id'] ?>" <?= in_array((int)$flag['id'],$permissions[$member['id']]??[],true)?'checked':'' ?>> <?= e($flag['key']) ?></label><?php endforeach; ?></div><button class="button small" type="submit">Lưu phân quyền</button><?php else: ?><p class="muted">Quản trị viên toàn quyền trong dự án.</p><?php endif; ?></form><?php endforeach; ?></section>
<section class="panel"><div class="panel-head"><div><h2>Tạo tài khoản thành viên</h2><p>Tài khoản mới có quyền trong dự án này.</p></div></div><form method="post" action="<?= e(url('members/create')) ?>" class="form-grid"><?= csrf_field() ?><label>Họ tên<input name="name" required maxlength="160"></label><label>Email<input type="email" name="email" required></label><label>Mật khẩu tạm (tối thiểu 8 ký tự)<input type="password" name="password" minlength="8" required></label><label>Vai trò<select name="role"><option value="viewer">Viewer</option><option value="editor">Editor</option></select></label><label class="check-label"><input type="checkbox" name="can_view_audit"> Cho phép xem audit log</label><div class="wide"><strong>Features được sửa (dành cho Editor)</strong><div class="flag-permissions"><?php foreach($flags as $flag): ?><label><input type="checkbox" name="flag_ids[]" value="<?= (int)$flag['id'] ?>"> <?= e($flag['key']) ?></label><?php endforeach; ?></div></div><button class="button primary" type="submit">Tạo tài khoản</button></form></section></div>
